select *
from TB_CATEGORY
where PARENT = #{parentId}
  AND USE_YN = 'Y';

select *
from TB_CATEGORY
where CATEGORY_NAME = #{categoryName}
  and PARENT = #{parent}
  AND USE_YN = 'Y';

mapper.update:
update TB_CATEGORY
SET

    CATEGORY_NAME = #{categoryName},


    USE_YN = #{useYn},


    PARENT = #{parent},

MOD_ID = #{modId}
, MOD_DT = #{modDt}
WHERE CATEGORY_ID = #{categoryId}
